// math/exp_f32_table.c
//
// The table behind the 2^(n / 32) kernel of the f32 exp and pow in exp_log_f32.h: 256 bytes of
// powers of 2, and the coefficients of its cubic, kept apart from the log table so that exp links
// only this one.
//
// Generated by tools/math/exp_log_f32/gen_exp_log_f32.py, which works each value out with mpmath at
// 200 bits and rounds it once to double, and fits the cubic with Sollya's fpminimax.

#include "math/exp_log_f32.h"

